/**
 * Resolves the locale for a request: the session's stored choice, then `Accept-Language`, then the default.
 */
export async function resolveRequestLocale(runtime, context, options = {}) {
    const stored = await readSessionLocale(context, options.sessionKey ?? LOCALE_SESSION_KEY);
    // The locale endpoint explicitly selects English for a client-only language, even when the application's own
    // server locale list omits it. Base English resources are always loaded alongside the configured default.
    if (stored === BASE_LOCALE)
        return BASE_LOCALE;
    if (stored)
        return runtime.resolveLocale(stored);
    const accepted = parseAcceptLanguage(context.req.header('accept-language') ?? undefined);
    return runtime.resolvePreferredLocale(accepted);
}
/**
 * Puts the request's locale and a translator bound to it on the context.
 *
 * Mount it after the session middleware, which it reads the stored locale from. It awaits the locale's resources, so a
 * handler can translate synchronously without risking a silent fallback to the key.
 */
export function createI18nMiddleware(runtime, options = {}) {
    return async (context, next) => {
        const locale = await resolveRequestLocale(runtime, context, options);
        await runtime.ensureLocaleLoaded(locale);
        context.set(LOCALE_CONTEXT_KEY, locale);
        context.set(TRANSLATOR_CONTEXT_KEY, runtime.getFixedT(options.namespace ?? APP_NS, locale));
        await next();
    };

export function getRequestLocale(context) {
    return context.get(LOCALE_CONTEXT_KEY);
}
/**
 * Returns the translator installed for the current request, optionally bound to a namespace.
 *
 * The i18n middleware loads the request locale before installing this translator. A missing translator therefore
 * means the middleware did not run before the route, which is an application wiring error rather than an optional
 * request state.
 */
export function getRequestTranslator(context, namespace) {
    const translator = context.get(TRANSLATOR_CONTEXT_KEY);
    if (!translator) {
        throw new Error('Request translator is unavailable. Make sure the i18n HTTP middleware is mounted before the route.');
    }
    if (!namespace)
        return translator;
    return (key, options) => translator(key, {
        ...options,
        ns: options?.ns ?? namespace,
    });
}

